INSERT INTO projects (id, service_id, title, location_city, completion_year, summary, challenge_description, solution_description, specifications, before_image_url, after_image_url, is_featured, sort_order) VALUES
('proj-1', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Complete Misted Double Glazing Restoration', 'Bicester, Oxfordshire', '2024', 'Restored 14 misted and condensation-damaged double glazing units in a 1990s detached family home, retaining original mahogany frames.', 'The homeowner suffered from severe cloudiness between glass panes blocking garden views and reducing heating efficiency. Competitor quotes suggested replacing all window frames costing over £9,000.', 'The Window Doctor surveyed the property, precisely measured all 14 units, and manufactured custom Argon-filled Pilkington Optitherm double glazed units. All units were replaced in a single day at less than one-third of the competitor cost.', '["14 High-performance Argon sealed units", "Pilkington Optitherm Low-E Coating", "Swissspacer warm edge thermal spacers", "Total cost saving: 68% vs new frames", "Zero disruption to interior decoration"]'::jsonb, 'https://lh3.googleusercontent.com/aida-public/AB6AXuB4PgLGqLJswj_yOE9Fp-h7Bh-0gB3SEGKW6wM__fhYsI1vcAZwqvKhgzpVL7CPX7XDHfvLEFLucGEy4uNrBRgE-6Ygcy_HksxKYiVtZxOFrjkRG5UiALFDyTnqEFSdiMMHVQtQIoDIgwDQLyuJAjYBogUwBNPAh0jSMBy_zkHmL9gRXfOW6qtVeyd7XAcVNUXYynC-N2W5g5e1oWBK8e7f5qY9lqco1Xmr5MekrfBHfzcqTU0EIh2I', 'https://lh3.googleusercontent.com/aida-public/AB6AXuB9Fjn6wLLJZk7YeTa18NvqtxVCAuCLsPnhE3EOon6a9RSl8DqWeJ6DGpPN3B6yXvnBbK_8OP57skrmnRE00KFwtYNY4-Po01ZpW2IZL8dhW-KTZEIwNqYHLH2ZMj0dT9_rIRZNzmVr41RmOTyB57SKAxZYM20vaj7zwWoJac6g65mlm_vIk0VGIAHhRm2i2Cl3os08pjvua_ekNlYnUBydzWripfsDHkuMnFFqvYRAnr3YkGB7oUYnD2ugQDdU-jkp1w', true, 1),
INSERT INTO customer_reviews (project_id, customer_name, customer_location, service_category, rating, review_title, review_text, is_verified, review_date) VALUES
('proj-1', 'David & Sarah Henderson', 'Kingsmere, Bicester', 'Misted Glass Repair', 5, 'Saved us thousands on our windows!', 'Other companies told us we had to replace all window frames at huge expense. The Window Doctor came out the next day, surveyed the seals, and replaced only the glass. Fast, immaculate, and our home is warm again!', true, '2024-10-15'),
('proj-2', 'Dr. Edward Thorne', 'Summertown, Oxford', 'Bi-Fold Doors Installation', 5, 'Exceptional craftsmanship and precision', 'From the initial survey to the final fitment, the team demonstrated master-level skill. The bi-folds glide with one finger and transformed our rear extension. Highly recommended.', true, '2024-11-02'),
('proj-3', 'Mrs. Gillian Wright', 'Bloxham, Banbury', 'Warm Roof Conversion', 5, 'We finally have our living space back', 'We can now sit in our conservatory even in sub-zero January weather. The sound of rain is completely muted, and the lighting looks stunning. 40 years of experience truly shows.', true, '2024-11-20'),
(NULL, 'Mark & Claire Davies', 'Kidlington, Oxfordshire', 'Composite Door & Windows', 5, 'Prompt, polite and outstanding quality', 'Replaced our dated front door with a solid core composite and fitted new triple glazed casement windows. Great communication from the office and clean, tidy installers.', true, '2024-12-05');
